// Coverage closure for the qs-ques AXI master with its UVM testbench as the environment.
//
// fv_agent_<test> is generated by `fvgen --agent <test>` (fvproc.py) from the whole test: the CPU-side
// mem_agent (driver, monitor, the test's sequence) drives the DUT, the reactive axi_slave_agent answers it.
// Every choice the testbench makes at random ($urandom_range, randomize() under the class constraints)
// is a free value of the model; nothing else is free (axi_mem_model read data is: it is outside the env).
//
// The covers are axi_coverage's bins (uvm_tb/env/axi_coverage.svh: plain counters, sampled by
// axi_coverage::write() for every request mem_monitor sees accepted). A cover trace is a run of the real
// testbench: its choices are what fv_replay.sv replays in simulation.
`include "fv_tool.svh"
`ifndef FV_TEST
`define FV_TEST fv_agent_axi_rw_rand_test
`endif
module axi_cov_top (
  input logic clk
);
  `include "prim_assert.sv"

  // tb_top: reset_n low, then high after RESET_CYCLES (5) edges
  logic [2:0] rst_cnt = '0;
  logic       reset_n = 1'b0;
  always_ff @(posedge clk) begin
    if (rst_cnt != 3'd5) rst_cnt <= rst_cnt + 1'b1;
    if (rst_cnt == 3'd4) reset_n <= 1'b1;
  end
  wire reset = !reset_n;                  // (the default reset of the prim_assert macros)

  // ---------------------------------------------------------------- CPU-MEM bus (mem_bus_if)
  logic         cpu_mem_valid, cpu_mem_ready, cpu_mem_wr, mem_cpu_valid, mem_cpu_ready;
  logic [3:0]   cpu_mem_id, mem_cpu_id;
  logic [31:0]  cpu_mem_addr;
  logic [15:0]  cpu_mem_byte_en;
  logic [127:0] cpu_mem_wr_data, mem_cpu_rd_data;
  // ---------------------------------------------------------------- AXI bus (axi_bus_if)
  logic        axi_awvalid, axi_awready, axi_wvalid, axi_wready, axi_wlast, axi_bvalid, axi_bready;
  logic        axi_arvalid, axi_arready, axi_rvalid, axi_rready, axi_rlast;
  logic [2:0]  axi_awid, axi_arid, axi_bid, axi_rid, axi_awsize, axi_arsize;
  logic [1:0]  axi_awlen, axi_arlen;
  logic [31:0] axi_awaddr, axi_araddr, axi_wdata, axi_rdata;
  logic [3:0]  axi_wstrb;

  logic        tb_bound_hit;
`ifndef FV_TEST_PARAMS
`define FV_TEST_PARAMS
`endif
  `FV_TEST `FV_TEST_PARAMS u_tb (
    .clk, .reset_n,
    .cpu_mem_valid, .cpu_mem_id, .cpu_mem_addr, .cpu_mem_byte_en, .cpu_mem_wr, .cpu_mem_wr_data, .cpu_mem_ready,
    .mem_cpu_valid, .mem_cpu_id, .mem_cpu_rd_data, .mem_cpu_ready,
    .axi_awvalid, .axi_awid, .axi_awaddr, .axi_awlen, .axi_awsize, .axi_awready,
    .axi_wvalid, .axi_wdata, .axi_wstrb, .axi_wlast, .axi_wready,
    .axi_bvalid, .axi_bid, .axi_bready,
    .axi_arvalid, .axi_arid, .axi_araddr, .axi_arlen, .axi_arsize, .axi_arready,
    .axi_rvalid, .axi_rid, .axi_rdata, .axi_rlast, .axi_rready,
    .fv_bound_hit(tb_bound_hit), .fv_uvm_error()
  );

  axi_master DUT (
    .clk, .reset_n,
    .cpu_mem_valid_i(cpu_mem_valid), .cpu_mem_id_i(cpu_mem_id), .cpu_mem_addr_i(cpu_mem_addr),
    .cpu_mem_byte_en_i(cpu_mem_byte_en), .cpu_mem_wr_i(cpu_mem_wr), .cpu_mem_wr_data_i(cpu_mem_wr_data),
    .cpu_mem_ready_o(cpu_mem_ready),
    .mem_cpu_valid_o(mem_cpu_valid), .mem_cpu_id_o(mem_cpu_id), .mem_cpu_rd_data_o(mem_cpu_rd_data),
    .mem_cpu_ready_i(mem_cpu_ready),
    .axi_awvalid_o(axi_awvalid), .axi_awid_o(axi_awid), .axi_awaddr_o(axi_awaddr), .axi_awlen_o(axi_awlen),
    .axi_awsize_o(axi_awsize), .axi_awready_i(axi_awready),
    .axi_wvalid_o(axi_wvalid), .axi_wdata_o(axi_wdata), .axi_wstrb_o(axi_wstrb), .axi_wlast_o(axi_wlast),
    .axi_wready_i(axi_wready),
    .axi_bvalid_i(axi_bvalid), .axi_bid_i(axi_bid), .axi_bready_o(axi_bready),
    .axi_arvalid_o(axi_arvalid), .axi_arid_o(axi_arid), .axi_araddr_o(axi_araddr), .axi_arlen_o(axi_arlen),
    .axi_arsize_o(axi_arsize), .axi_arready_i(axi_arready),
    .axi_rvalid_i(axi_rvalid), .axi_rid_i(axi_rid), .axi_rdata_i(axi_rdata), .axi_rlast_i(axi_rlast),
    .axi_rready_o(axi_rready)
  );

  // ---------------------------------------------------------------- axi_coverage::write()
  // sampled when mem_monitor publishes an accepted request (reset_n && cpu_mem_valid && cpu_mem_ready)
  localparam int LANE_BYTES = 4, NUM_LANES = 4, LINE_BITS = 4;
  wire acc = reset_n && cpu_mem_valid && cpu_mem_ready;
  logic [2:0] lanes, first_lane;          // axi_utils::num_lanes / first_lane
  logic [4:0] fb, nb;                     // axi_utils::first_byte / num_bytes
  always_comb begin
    lanes = '0; first_lane = '0; fb = '0; nb = '0;
    for (int l = NUM_LANES - 1; l >= 0; l--) if (|cpu_mem_byte_en[l*LANE_BYTES +: LANE_BYTES]) first_lane = 3'(l);
    for (int l = 0; l < NUM_LANES; l++) if (|cpu_mem_byte_en[l*LANE_BYTES +: LANE_BYTES]) lanes = lanes + 1'b1;
    for (int i = 15; i >= 0; i--) if (cpu_mem_byte_en[i]) fb = 5'(i);
    for (int i = 0; i < 16; i++) if (cpu_mem_byte_en[i]) nb = nb + 1'b1;
  end
  wire       head_partial = (fb % LANE_BYTES) != 0;
  wire       tail_partial = ((fb + nb) % LANE_BYTES) != 0;
  wire [2:0] axi_id = cpu_mem_addr[LINE_BITS +: 3];        // axi_utils::axi_id_of

  // A cover per bin, named after it (concurrent covers keep their label through yosys: the cover trace of
  // g_kind[1].g_lanes[2].g_at[0].cov_cross is the one for cross_hits["WR_lanes2_at0"]); k: 0 RD, 1 WR
`define BIN(__name, __prop) __name: cover property (@(posedge clk) (__prop));
  // cross_hits["<RD|WR>_lanes<n>_at<f>"]: kind x lanes x first_lane (f + n <= NUM_LANES)
  for (genvar k = 0; k < 2; k++) begin : g_kind
    for (genvar n = 1; n <= NUM_LANES; n++) begin : g_lanes
      for (genvar f = 0; f + n <= NUM_LANES; f++) begin : g_at
        `BIN(cov_cross, acc && cpu_mem_wr == k && lanes == n && first_lane == f)
      end
    end
    // shape_hits["<RD|WR>_head<h>_tail<t>"]
    for (genvar h = 0; h < 2; h++) begin : g_head
      for (genvar t = 0; t < 2; t++) begin : g_tail
        `BIN(cov_shape, acc && cpu_mem_wr == k && head_partial == h && tail_partial == t)
      end
    end
  end
  // id_hits[axi id], mem_id_hits[mem_id]
  for (genvar i = 0; i < 8; i++) begin : g_axi_id
    `BIN(cov_axi_id, acc && axi_id == i)
  end
  for (genvar i = 0; i < 16; i++) begin : g_mem_id
    `BIN(cov_mem_id, acc && cpu_mem_id == i)
  end

  // ---------------------------------------------------------------- longer runs (not axi_coverage bins)
  // they need both agents over many cycles (AXI latencies, ready bits, R/B responses): their replays check the
  // model against the testbench beyond the first request
  logic [2:0] n_acc = '0;
  always_ff @(posedge clk) if (acc && n_acc != 3'd7) n_acc <= n_acc + 1'b1;
  `BIN(env_rd_response, reset_n && mem_cpu_valid && mem_cpu_ready)
  `BIN(env_wr_response, reset_n && axi_bvalid && axi_bready)
  `BIN(env_four_requests, acc && n_acc == 3'd3)
  // the DUT's 4-entry read buffer full: four read responses received and not yet returned to the CPU
  `BIN(env_rd_buffer_full, &DUT.axi_rd_buffer_valid_q)

`undef BIN

  // the testbench model stays inside its modelled bounds (queue depths, counters, choices per edge)
  `ASSERT(tb_bounds, !tb_bound_hit, clk, 1'b0)
endmodule
